import { fileURLToPath } from 'node:url';
import { ModelCatalog } from './catalog';
import { loadCatalogEntries } from './file';

/**
 * The models.dev snapshot that ships in the tree (`packages/catalog/data`) and in the
 * runtime image (`dist/data`, copied by `scripts/bundle.mjs`). It is the OFFLINE
 * pricing fallback: regenerated by hand with `pnpm --filter @gulley/catalog snapshot`
 * (the only place models.dev is fetched — never at runtime, never on a schedule).
 */

/** The package-relative snapshot path (also correct from a bundled entry, whose
 *  `../data` is `dist/data`). */
export const BUNDLED_SNAPSHOT_PATH: string = fileURLToPath(
  new URL('../data/models-dev.snapshot.json', import.meta.url),
);

/** Where this process reads the snapshot: `GULLEY_CATALOG_SNAPSHOT` when set (the
 *  image points it at the copied file, like `GULLEY_MIGRATIONS_DIR`), else the
 *  package-relative default. Resolved at call time, not import time. */
export function bundledSnapshotPath(): string {
  return process.env['GULLEY_CATALOG_SNAPSHOT'] ?? BUNDLED_SNAPSHOT_PATH;
}

/** Load the bundled snapshot into a fresh catalog. Throws if the file is missing or
 *  malformed — a broken snapshot is a broken build, not a silent $0. */
export function loadBundledSnapshot(path: string = bundledSnapshotPath()): ModelCatalog {
  return new ModelCatalog(loadCatalogEntries(path));
}
